schemas.202609170003_repair_visit_rating_half_st:
-- Repair projects that were initialized before half-point ratings were introduced.
-- This is intentionally idempotent so it can also be run directly in the SQL Editor.
alter table public.visits
  drop constraint if exists visits_rating_check;

alter table public.visits
  alter column rating type numeric(2,1) using rating::numeric(2,1);

alter table public.visits
  add constraint visits_rating_check
  check (rating between 0.5 and 5 and rating * 2 = trunc(rating * 2));

-- Keep the existing numbered pins and allow the named square/round pins.
alter table public.visits
  drop constraint if exists visits_marker_style_check;

alter table public.visits
  add constraint visits_marker_style_check
  check (
    marker_style ~ '^((color|black)-[0-9]+|(square|round)-(cat|plane|gamepad|camp|museum|night|car|forest|mountain|water|park)-(color|black))$'
  );

schemas.202609280001_trip_timetables.sql:
-- Apply after 202609190001. Safe to run as one transaction in SQL Editor.
begin;

do $$ begin
  if not exists (select 1 from pg_catalog.pg_constraint
    where conname = 'places_id_group_unique' and conrelid = 'public.places'::regclass)
    and pg_catalog.to_regclass('public.places_id_group_unique') is null then
