create table if not exists public.trips (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 120),
  start_date date not null,
  end_date date not null check (end_date >= start_date),
  time_zone text not null default 'Asia/Seoul',
  version integer not null default 1 check (version > 0),
  created_by uuid not null references public.profiles(id),
  updated_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (id, group_id)
);
create table if not exists public.schedule_items (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  trip_id uuid not null,
  place_id uuid not null,
  starts_at timestamp without time zone not null,
  ends_at timestamp without time zone not null check (ends_at > starts_at),
  title text not null check (char_length(btrim(title)) between 1 and 120),
  note text not null default '' check (char_length(note) <= 3000),
  marker_style text not null default 'black-9' check (marker_style ~ '^((color|black)-([1-9]|1[0-6])|(square|round)-(cat|plane|gamepad|camp|museum|night|car|forest|mountain|water|park)-(color|black))$'),
  version integer not null default 1 check (version > 0),
  created_by uuid not null references public.profiles(id),
  updated_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  foreign key (trip_id, group_id) references public.trips(id, group_id) on delete cascade,
  foreign key (place_id, group_id) references public.places(id, group_id)
);
create index if not exists trips_group_dates_idx on public.trips(group_id, start_date) where deleted_at is null;
create index if not exists schedule_trip_time_idx on public.schedule_items(trip_id, starts_at) where deleted_at is null;
create index if not exists schedule_place_idx on public.schedule_items(place_id, group_id);

create or replace function private.validate_trip() returns trigger
language plpgsql set search_path = '' as $$
begin
  if not exists(select 1 from pg_catalog.pg_timezone_names where name = new.time_zone) then
    raise exception '유효한 IANA 시간대를 선택해 주세요.' using errcode = '22023';
  end if;
  if not isfinite(new.start_date) or not isfinite(new.end_date) then
    raise exception '유효한 여행 날짜를 입력해 주세요.' using errcode = '22023';
  end if;
  if tg_op = 'UPDATE' and (new.id <> old.id or new.group_id <> old.group_id) then
    raise exception '여행의 소속 지도는 변경할 수 없습니다.' using errcode = '22023';
  end if;
  if new.deleted_at is null and exists(select 1 from public.schedule_items
    where trip_id = new.id and deleted_at is null
      and (starts_at < new.start_date::timestamp or ends_at > (new.end_date + 1)::timestamp)) then
    raise exception '새 여행 기간 밖의 일정을 먼저 옮기거나 삭제해 주세요.' using errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists trips_validate on public.trips;
create trigger trips_validate before insert or update on public.trips
  for each row execute function private.validate_trip();

create or replace function private.validate_schedule_item() returns trigger
language plpgsql set search_path = '' as $$
declare parent public.trips;
begin
  -- Every supported write locks the trip first, then its items.
  select * into parent from public.trips where id = new.trip_id for update;
  if not found or parent.group_id <> new.group_id then
    raise exception '여행과 일정의 지도가 일치하지 않습니다.' using errcode = '22023';
  end if;
  if tg_op = 'UPDATE' and (new.trip_id <> old.trip_id or new.group_id <> old.group_id or new.id <> old.id) then
    raise exception '일정의 소속 여행은 변경할 수 없습니다.' using errcode = '22023';
  end if;
  if new.deleted_at is null and (parent.deleted_at is not null
    or not isfinite(new.starts_at) or not isfinite(new.ends_at)
    or new.starts_at < parent.start_date::timestamp or new.ends_at > (parent.end_date + 1)::timestamp) then
    raise exception '일정은 여행 기간 안에 있어야 합니다.' using errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists schedule_items_validate on public.schedule_items;
create trigger schedule_items_validate before insert or update on public.schedule_items
  for each row execute function private.validate_schedule_item();

alter table public.trips enable row level security;
alter table public.schedule_items enable row level security;
drop policy if exists trips_read on public.trips;
create policy trips_read on public.trips for select to authenticated
  using (deleted_at is null and private.is_group_member(group_id));
drop policy if exists schedule_items_read on public.schedule_items;
create policy schedule_items_read on public.schedule_items for select to authenticated
  using (deleted_at is null and private.is_group_member(group_id)
    and exists(select 1 from public.trips t where t.id = trip_id and t.deleted_at is null));
revoke all on public.trips, public.schedule_items from public, anon, authenticated;
grant select on public.trips, public.schedule_items to authenticated;

-- Only these RPCs can write. Never trust caller-supplied authors or group IDs
-- for updates, and never grant these functions to anonymous callers.
create or replace function public.save_trip(payload jsonb) returns public.trips
language plpgsql security definer set search_path = '' as $$
declare result public.trips; caller uuid := auth.uid(); target uuid := (payload->>'id')::uuid;
begin
  if caller is null then raise exception '로그인이 필요합니다.' using errcode = '42501'; end if;
  if target is null then
    if not private.is_group_member((payload->>'groupId')::uuid, caller) then
      raise exception '이 지도의 멤버만 여행을 만들 수 있습니다.' using errcode = '42501';
    end if;
    insert into public.trips(group_id, name, start_date, end_date, time_zone, created_by, updated_by)
    values ((payload->>'groupId')::uuid, btrim(payload->>'name'), (payload->>'startDate')::date,
      (payload->>'endDate')::date, coalesce(payload->>'timeZone', 'Asia/Seoul'), caller, caller)
    returning * into result;
  else
    select * into result from public.trips where id = target and deleted_at is null for update;
    if not found or not private.is_group_member(result.group_id, caller) then
      raise exception '여행을 찾을 수 없거나 권한이 없습니다.' using errcode = '42501';
    end if;
    if result.version is distinct from (payload->>'version')::integer then
      raise exception '다른 멤버가 먼저 수정했습니다. 최신 일정을 확인해 주세요.' using errcode = '40001';
    end if;
    update public.trips set name = btrim(payload->>'name'), start_date = (payload->>'startDate')::date,
      end_date = (payload->>'endDate')::date, time_zone = payload->>'timeZone',
      version = version + 1, updated_by = caller where id = target returning * into result;
  end if;
  return result;
end $$;

create or replace function public.delete_trip(target_id uuid, expected_version integer) returns void
language plpgsql security definer set search_path = '' as $$
declare parent public.trips; caller uuid := auth.uid();
begin
  select * into parent from public.trips where id = target_id and deleted_at is null for update;
  if not found or caller is null or not private.is_group_member(parent.group_id, caller) then
    raise exception '여행을 찾을 수 없거나 권한이 없습니다.' using errcode = '42501';
  end if;
  if parent.version is distinct from expected_version then
    raise exception '다른 멤버가 먼저 수정했습니다. 최신 일정을 확인해 주세요.' using errcode = '40001';
  end if;
  update public.schedule_items set deleted_at = now(), updated_by = caller, version = version + 1
    where trip_id = target_id and deleted_at is null;
  update public.trips set deleted_at = now(), updated_by = caller, version = version + 1 where id = target_id;
end $$;

create or replace function public.save_schedule_item(target_trip_id uuid, payload jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare parent public.trips; previous public.schedule_items; caller uuid := auth.uid();
  target uuid := (payload->>'id')::uuid; location_id uuid := (payload->'place'->>'id')::uuid;
  location jsonb := payload->'place';
begin
  select * into parent from public.trips where id = target_trip_id and deleted_at is null for update;
  if not found or caller is null or not private.is_group_member(parent.group_id, caller) then
    raise exception '여행을 찾을 수 없거나 권한이 없습니다.' using errcode = '42501';
  end if;
  if target is not null then
    select * into previous from public.schedule_items where id = target and trip_id = target_trip_id and deleted_at is null for update;
    if not found then raise exception '일정을 찾을 수 없습니다.' using errcode = '22023'; end if;
    if previous.version is distinct from (payload->>'version')::integer then
      raise exception '다른 멤버가 먼저 수정했습니다. 최신 일정을 확인해 주세요.' using errcode = '40001';
    end if;
  end if;
  if location_id is not null then
    if not exists(select 1 from public.places where id = location_id and group_id = parent.group_id) then
      raise exception '이 지도의 장소만 사용할 수 있습니다.' using errcode = '42501';
    end if;
  else
    if location->>'provider' = 'kakao' and nullif(location->>'providerPlaceId', '') is not null then
      insert into public.places(group_id, provider, provider_place_id, name, address, category, latitude, longitude, created_by)
      values(parent.group_id, 'kakao', location->>'providerPlaceId', location->>'name', coalesce(location->>'address',''),
        coalesce(location->>'category',''), (location->>'latitude')::numeric, (location->>'longitude')::numeric, caller)
      on conflict (group_id, provider, provider_place_id) where provider_place_id is not null do nothing
      returning id into location_id;
      if location_id is null then select id into location_id from public.places where group_id = parent.group_id
        and provider = 'kakao' and provider_place_id = location->>'providerPlaceId'; end if;
    else
      insert into public.places(group_id, provider, name, address, category, latitude, longitude, created_by)
      values(parent.group_id, 'manual', location->>'name', coalesce(location->>'address',''), coalesce(location->>'category','직접 지정'),
        (location->>'latitude')::numeric, (location->>'longitude')::numeric, caller) returning id into location_id;
    end if;
  end if;
  if target is null then
    insert into public.schedule_items(group_id, trip_id, place_id, starts_at, ends_at, title, note, marker_style, created_by, updated_by)
    values(parent.group_id, target_trip_id, location_id, (payload->>'startsAt')::timestamp, (payload->>'endsAt')::timestamp,
      btrim(payload->>'title'), coalesce(payload->>'note',''), coalesce(payload->>'markerStyle','black-9'), caller, caller)
    returning id into target;
  else
    update public.schedule_items set place_id = location_id, starts_at = (payload->>'startsAt')::timestamp,
      ends_at = (payload->>'endsAt')::timestamp, title = btrim(payload->>'title'), note = coalesce(payload->>'note',''),
      marker_style = coalesce(payload->>'markerStyle','black-9'), version = version + 1, updated_by = caller where id = target;
  end if;
  -- Trip version also covers child changes, protecting a stale whole-trip delete.
  update public.trips set version = version + 1, updated_by = caller where id = parent.id;
  return target;
end $$;

create or replace function public.delete_schedule_item(target_trip_id uuid, target_id uuid, expected_version integer) returns void
language plpgsql security definer set search_path = '' as $$
declare parent public.trips; caller uuid := auth.uid();
begin
  select * into parent from public.trips where id = target_trip_id and deleted_at is null for update;
  if not found or caller is null or not private.is_group_member(parent.group_id, caller) then
    raise exception '여행을 찾을 수 없거나 권한이 없습니다.' using errcode = '42501';
  end if;
  update public.schedule_items set deleted_at = now(), updated_by = caller, version = version + 1
    where id = target_id and trip_id = target_trip_id and version = expected_version and deleted_at is null;
  if not found then raise exception '다른 멤버가 먼저 수정했습니다. 최신 일정을 확인해 주세요.' using errcode = '40001'; end if;
  update public.trips set version = version + 1, updated_by = caller where id = parent.id;
end $$;

revoke all on function public.save_trip(jsonb), public.delete_trip(uuid, integer),
  public.save_schedule_item(uuid, jsonb), public.delete_schedule_item(uuid, uuid, integer) from public, anon, authenticated;
grant execute on function public.save_trip(jsonb), public.delete_trip(uuid, integer),
  public.save_schedule_item(uuid, jsonb), public.delete_schedule_item(uuid, uuid, integer) to authenticated;
revoke all on function private.validate_trip(), private.validate_schedule_item() from public, anon, authenticated;
commit;

schemas.202609290001_trip_route_cache.sql:
begin;

-- The route is generated only after an explicit user action. Cache keys cover
-- the trip, date, map provider, and ordered location sequence.
create table if not exists public.trip_route_cache (
  trip_id uuid not null references public.trips(id) on delete cascade,
  route_date date not null,
  provider text not null check (provider in ('kakao', 'osm')),
  signature text not null check (signature ~ '^[0-9a-f]{64}$'),
  route_kind text not null check (route_kind in ('road', 'straight')),
  route_points jsonb not null check (case when jsonb_typeof(route_points) = 'array' then jsonb_array_length(route_points) between 2 and 4000 else false end),
  distance_meters integer check (distance_meters is null or distance_meters >= 0),
  duration_seconds integer check (duration_seconds is null or duration_seconds >= 0),
  created_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  primary key (trip_id, route_date, provider, signature)
);

alter table public.trip_route_cache enable row level security;
drop policy if exists trip_route_cache_read on public.trip_route_cache;
create policy trip_route_cache_read on public.trip_route_cache for select to authenticated
  using (exists (
    select 1 from public.trips t
    where t.id = trip_id and t.deleted_at is null and private.is_group_member(t.group_id)
  ));
revoke all on public.trip_route_cache from public, anon, authenticated;
grant select on public.trip_route_cache to authenticated;

drop function if exists public.save_trip_route(uuid, date, text, text, text, jsonb, integer, integer);
create function public.save_trip_route(
  target_trip_id uuid,
  p_route_date date,
  route_provider text,
  route_signature text,
  route_kind text,
  route_points jsonb,
  distance_meters integer default null,
  duration_seconds integer default null
) returns public.trip_route_cache
language plpgsql security definer set search_path = '' as $$
declare parent public.trips; caller uuid := auth.uid(); result public.trip_route_cache;
begin
  select * into parent from public.trips where id = target_trip_id and deleted_at is null for update;
  if not found or caller is null or not private.is_group_member(parent.group_id, caller) then
    raise exception '여행을 찾을 수 없거나 권한이 없습니다.' using errcode = '42501';
  end if;
  if p_route_date < parent.start_date or p_route_date > parent.end_date then
    raise exception '여행 기간 밖의 날짜입니다.' using errcode = '22023';
  end if;
  if route_provider not in ('kakao', 'osm') or route_signature !~ '^[0-9a-f]{64}$'
    or route_kind not in ('road', 'straight') or jsonb_typeof(route_points) is distinct from 'array' then
    raise exception '경로 정보가 올바르지 않습니다.' using errcode = '22023';
  end if;
  if jsonb_array_length(route_points) not between 2 and 4000 or exists (
    select 1 from pg_catalog.jsonb_array_elements(route_points) as route_point(value)
    where case
      when jsonb_typeof(route_point.value) is distinct from 'object' then true
      when jsonb_typeof(route_point.value->'latitude') is distinct from 'number' then true
      when jsonb_typeof(route_point.value->'longitude') is distinct from 'number' then true
      else (route_point.value->>'latitude')::numeric not between -90 and 90
        or (route_point.value->>'longitude')::numeric not between -180 and 180
    end
  ) then
    raise exception '경로 정보가 올바르지 않습니다.' using errcode = '22023';
  end if;
  insert into public.trip_route_cache(trip_id, route_date, provider, signature, route_kind, route_points, distance_meters, duration_seconds, created_by)
  values (target_trip_id, p_route_date, route_provider, route_signature, route_kind, route_points, distance_meters, duration_seconds, caller)
  on conflict (trip_id, route_date, provider, signature) do update set
    route_kind = excluded.route_kind,
    route_points = excluded.route_points,
    distance_meters = excluded.distance_meters,
    duration_seconds = excluded.duration_seconds
  returning * into result;
  return result;
end $$;

revoke all on function public.save_trip_route(uuid, date, text, text, text, jsonb, integer, integer) from public, anon, authenticated;
grant execute on function public.save_trip_route(uuid, date, text, text, text, jsonb, integer, integer) to authenticated;
commit;

schemas.202610020001_visit_reliability.sql:
begin;

alter table public.visits add column if not exists client_request_id uuid;
alter table public.visits add column if not exists last_request_id uuid;
alter table public.visits add column if not exists purge_started_at timestamptz;
create unique index if not exists visits_request_unique on public.visits(created_by, client_request_id) where client_request_id is not null;
alter table public.visit_photos add column if not exists deleted_at timestamptz;
alter table public.visit_photos add column if not exists client_file_id uuid;
alter table public.visit_photos add column if not exists content_hash text;
alter table public.visit_photos add column if not exists upload_state text not null default 'complete' check (upload_state in ('pending','complete'));
create unique index if not exists visit_photo_request_unique on public.visit_photos(visit_id, client_file_id) where client_file_id is not null;

create or replace function public.save_visit(input jsonb, request_id uuid, creating boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare caller uuid := auth.uid(); gid uuid := (input->>'groupId')::uuid; v public.visits; pid uuid; person uuid;
begin
  if request_id is null then raise exception '요청 ID가 필요합니다.'; end if;
  if caller is null or not private.is_group_member(gid, caller) then raise exception '이 지도에 기록할 권한이 없습니다.' using errcode='42501'; end if;
  perform 1 from public.groups where id=gid for update;
  if creating then
    select * into v from public.visits where created_by=caller and client_request_id=request_id;
    if found then
      if v.group_id<>gid or v.deleted_at is not null then raise exception '이미 삭제되거나 변경된 요청입니다.' using errcode='40001'; end if;
      return jsonb_build_object('id',v.id,'version',v.version,'placeId',v.place_id);
    end if;
  else
    select * into v from public.visits where id=(input->>'id')::uuid and group_id=gid and deleted_at is null for update;
    if not found then raise exception '방문 기록을 찾지 못했습니다.' using errcode='P0002'; end if;
    if v.last_request_id=request_id then return jsonb_build_object('id',v.id,'version',v.version,'placeId',v.place_id); end if;
    if input->>'version' is null or v.version<>(input->>'version')::integer then raise exception '다른 멤버가 먼저 수정했습니다.' using errcode='40001'; end if;
  end if;
  for person in select jsonb_array_elements_text(input->'participantIds')::uuid loop
    if not private.is_group_member(gid,person) then raise exception '이 지도에 속하지 않은 참여자입니다.' using errcode='42501'; end if;
  end loop;
  if creating then
    if input->'place'->>'provider'='kakao' then
      select id into pid from public.places where group_id=gid and provider='kakao' and provider_place_id=input->'place'->>'providerPlaceId';
    end if;
    if pid is null then
      insert into public.places(group_id,provider,provider_place_id,name,address,category,latitude,longitude,created_by)
      values(gid,input->'place'->>'provider',input->'place'->>'providerPlaceId',input->'place'->>'name',input->'place'->>'address',input->'place'->>'category',(input->'place'->>'latitude')::numeric,(input->'place'->>'longitude')::numeric,caller) returning id into pid;
    end if;
    insert into public.visits(group_id,place_id,visited_on,is_planned,title,note,rating,tags,marker_style,created_by,updated_by,client_request_id,last_request_id)
    values(gid,pid,(input->>'visitedOn')::date,(input->>'isPlanned')::boolean,input->>'title',input->>'note',(input->>'rating')::numeric,array(select jsonb_array_elements_text(input->'tags')),input->>'markerStyle',caller,caller,request_id,request_id) returning * into v;
  else
    update public.visits set visited_on=(input->>'visitedOn')::date,is_planned=(input->>'isPlanned')::boolean,title=input->>'title',note=input->>'note',rating=(input->>'rating')::numeric,tags=array(select jsonb_array_elements_text(input->'tags')),marker_style=input->>'markerStyle',updated_by=caller,version=version+1,last_request_id=request_id where id=v.id returning * into v;
    delete from public.visit_participants where visit_id=v.id;
  end if;
  insert into public.visit_participants(visit_id,user_id) select v.id, jsonb_array_elements_text(input->'participantIds')::uuid on conflict do nothing;
  return jsonb_build_object('id',v.id,'version',v.version,'placeId',v.place_id);
end $$;

create or replace function public.reserve_visit_photo(target_id uuid, file_id uuid, file_hash text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v public.visits; p public.visit_photos; total integer;
begin
  if file_id is null then raise exception '사진 요청 ID가 필요합니다.'; end if;
  select * into v from public.visits where id=target_id and deleted_at is null for update;
  if not found or not private.is_group_member(v.group_id) then raise exception '사진을 추가할 권한이 없습니다.' using errcode='42501'; end if;
  select * into p from public.visit_photos where visit_id=target_id and client_file_id=file_id;
  if found then
    if p.deleted_at is not null then raise exception '이미 삭제된 사진 요청입니다.'; end if;
    if p.content_hash<>file_hash then raise exception '동일한 요청으로 다른 사진을 올릴 수 없습니다.'; end if;
    return to_jsonb(p);
  end if;
  select count(*) into total from public.visit_photos where visit_id=target_id and deleted_at is null;
  if total>=5 then raise exception '사진은 최대 5장까지 추가할 수 있어요.'; end if;
  insert into public.visit_photos(visit_id,client_file_id,content_hash,storage_path,sort_order,uploaded_by,upload_state)
  values(target_id,file_id,file_hash,v.group_id::text||'/'||target_id::text||'/'||file_id::text||'.webp',total,auth.uid(),'pending') returning * into p;
  return to_jsonb(p);
end $$;

create or replace function public.complete_visit_photo(target_id uuid, file_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v public.visits;
begin
  select * into v from public.visits where id=target_id and deleted_at is null for update;
  if not found or not private.is_group_member(v.group_id) then raise exception '사진을 저장할 권한이 없습니다.' using errcode='42501'; end if;
  update public.visit_photos set upload_state='complete' where visit_id=target_id and client_file_id=file_id and deleted_at is null;
  if not found then raise exception '사진 요청이 만료되었거나 삭제되었습니다.'; end if;
end $$;

create or replace function public.restore_visit(target_id uuid, expected_version integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v public.visits;
begin
  select * into v from public.visits where id=target_id for update;
  if not found or not private.is_group_member(v.group_id) then raise exception '복원할 권한이 없습니다.' using errcode='42501'; end if;
  if v.deleted_at is null then return jsonb_build_object('id',v.id,'version',v.version); end if;
  if v.deleted_at<=now()-interval '30 days' or v.purge_started_at is not null then raise exception '복원 기간이 지났습니다.' using errcode='P0002'; end if;
  if expected_version is null or v.version<>expected_version then raise exception '이미 변경된 기록입니다.' using errcode='40001'; end if;
  update public.visits set deleted_at=null,updated_by=auth.uid(),version=version+1,last_request_id=null where id=target_id returning * into v;
  return jsonb_build_object('id',v.id,'version',v.version);
end $$;

-- Claim expired rows before touching Storage; restoration cannot race cleanup.
create or replace function public.claim_expired_visits()
returns setof public.visits language sql security definer set search_path = '' as $$
  update public.visits set purge_started_at=coalesce(purge_started_at,now()) where id in
    (select id from public.visits where deleted_at<=now()-interval '30 days' order by deleted_at limit 100 for update skip locked)
  returning *;
$$;
revoke all on function public.claim_expired_visits() from public,anon,authenticated;
grant execute on function public.claim_expired_visits() to service_role;
-- Old DB-only purge would orphan Storage files. Use the authenticated maintenance endpoint.
create or replace function public.purge_expired_deleted_visits() returns integer language plpgsql security definer set search_path='' as $$ begin raise exception 'Use the Storage-aware maintenance endpoint'; end $$;
revoke all on function public.save_visit(jsonb,uuid,boolean), public.reserve_visit_photo(uuid,uuid,text),public.complete_visit_photo(uuid,uuid),public.restore_visit(uuid,integer) from public,anon;
grant execute on function public.save_visit(jsonb,uuid,boolean),public.reserve_visit_photo(uuid,uuid,text),public.complete_visit_photo(uuid,uuid),public.restore_visit(uuid,integer) to authenticated;

-- Abandoned editor files are not part of drafts. Release their slots after seven days.
create or replace function public.release_stale_photo_reservations()
returns integer language plpgsql security definer set search_path='' as $$
declare target public.visits; affected integer; total integer:=0;
begin
  for target in select v.* from public.visits v where v.deleted_at is null and exists
    (select 1 from public.visit_photos p where p.visit_id=v.id and p.upload_state='pending' and p.deleted_at is null and p.created_at<now()-interval '7 days') limit 100 for update skip locked loop
    update public.visit_photos set deleted_at=now() where visit_id=target.id and upload_state='pending' and deleted_at is null and created_at<now()-interval '7 days';
    get diagnostics affected=row_count; total:=total+affected;
  end loop;
  return total;
end $$;
revoke all on function public.release_stale_photo_reservations() from public,anon,authenticated;
grant execute on function public.release_stale_photo_reservations() to service_role;

commit;

schemas.202610070001_workspace_reliability.sql:
begin;
create table public.workspace_save_requests (
 user_id uuid not null references auth.users(id) on delete cascade,
 operation text not null, request_id uuid not null, result_id uuid not null,
 primary key(user_id,operation,request_id)
);
alter table public.workspace_save_requests enable row level security;

alter function public.save_trip(jsonb) rename to save_trip_legacy;
alter function public.save_schedule_item(uuid,jsonb) rename to save_schedule_item_legacy;

create function public.save_trip(payload jsonb) returns public.trips
language plpgsql security definer set search_path='' as $$
declare caller uuid:=auth.uid(); rid uuid:=(payload->>'requestId')::uuid; saved public.trips; gid uuid:=(payload->>'groupId')::uuid; replay uuid;
begin
 if caller is null or not private.is_group_member(gid,caller) then raise exception '이 지도의 멤버만 저장할 수 있습니다.' using errcode='42501'; end if;
 if rid is not null then
  perform pg_advisory_xact_lock(hashtextextended(caller::text||':trip:'||rid::text,0));
  select result_id into replay from public.workspace_save_requests where user_id=caller and operation='trip' and request_id=rid;
  if replay is not null then
   select * into saved from public.trips where id=replay and group_id=gid and deleted_at is null;
   if not found then raise exception '이미 삭제되거나 변경된 요청입니다.' using errcode='40001'; end if;
   return saved;
  end if;
 end if;
 saved:=public.save_trip_legacy(payload);
 if rid is not null then insert into public.workspace_save_requests values(caller,'trip',rid,saved.id); end if;
 return saved;
end $$;

create function public.save_schedule_item(target_trip_id uuid,payload jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare caller uuid:=auth.uid(); rid uuid:=(payload->>'requestId')::uuid; gid uuid; replay uuid; saved uuid;
begin
 select group_id into gid from public.trips where id=target_trip_id and deleted_at is null;
 if caller is null or gid is null or not private.is_group_member(gid,caller) then raise exception '이 여행에 저장할 권한이 없습니다.' using errcode='42501'; end if;
 if rid is not null then
  perform pg_advisory_xact_lock(hashtextextended(caller::text||':schedule:'||rid::text,0));
  select result_id into replay from public.workspace_save_requests where user_id=caller and operation='schedule' and request_id=rid;
  if replay is not null then
   if not exists(select 1 from public.schedule_items where id=replay and trip_id=target_trip_id and deleted_at is null) then raise exception '이미 삭제되거나 변경된 요청입니다.' using errcode='40001'; end if;
   return replay;
  end if;
 end if;
 saved:=public.save_schedule_item_legacy(target_trip_id,payload);
 if rid is not null then insert into public.workspace_save_requests values(caller,'schedule',rid,saved); end if;
 return saved;
end $$;

create function public.create_group_once(group_name text,request_id uuid) returns uuid
language plpgsql security definer set search_path='' as $$
declare caller uuid:=auth.uid(); saved uuid;
begin
 if caller is null then raise exception '로그인이 필요합니다.' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(caller::text||':group:'||request_id::text,0));
 select result_id into saved from public.workspace_save_requests r where r.user_id=caller and r.operation='group' and r.request_id=create_group_once.request_id;
 if saved is not null then
  if not exists(select 1 from public.groups where id=saved and created_by=caller) then raise exception '이미 삭제된 지도입니다.' using errcode='40001'; end if;
  return saved;
 end if;
 saved:=public.create_group(group_name);
 insert into public.workspace_save_requests values(caller,'group',request_id,saved);
 return saved;
end $$;

create function public.dashboard_group_counts() returns table(group_id uuid,visit_count bigint,member_count bigint)
language sql stable security invoker set search_path='' as $$
 select g.id,(select count(*) from public.visits v where v.group_id=g.id and v.deleted_at is null),
 (select count(*) from public.group_members m where m.group_id=g.id)
 from public.groups g where private.is_group_member(g.id,auth.uid())
$$;
revoke all on function public.save_trip(jsonb),public.save_schedule_item(uuid,jsonb),public.create_group_once(text,uuid),public.dashboard_group_counts() from public,anon;
grant execute on function public.save_trip(jsonb),public.save_schedule_item(uuid,jsonb),public.create_group_once(text,uuid),public.dashboard_group_counts() to authenticated;
revoke all on function public.save_trip_legacy(jsonb),public.save_schedule_item_legacy(uuid,jsonb) from public,anon,authenticated;
create or replace function public.save_visit(input jsonb, request_id uuid, creating boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare caller uuid := auth.uid(); gid uuid := (input->>'groupId')::uuid; v public.visits; pid uuid; person uuid;
begin
  if request_id is null then raise exception '요청 ID가 필요합니다.'; end if;
  if caller is null or not private.is_group_member(gid, caller) then raise exception '이 지도에 기록할 권한이 없습니다.' using errcode='42501'; end if;
  perform 1 from public.groups where id=gid for update;
  if creating then
    select * into v from public.visits where created_by=caller and client_request_id=request_id;
    if found then
      if v.group_id<>gid or v.deleted_at is not null then raise exception '이미 삭제되거나 변경된 요청입니다.' using errcode='40001'; end if;
      return jsonb_build_object('id',v.id,'version',v.version,'placeId',v.place_id);
    end if;
  else
    select * into v from public.visits where id=(input->>'id')::uuid and group_id=gid and deleted_at is null for update;
    if not found then raise exception '방문 기록을 찾지 못했습니다.' using errcode='P0002'; end if;
    if v.last_request_id=request_id then return jsonb_build_object('id',v.id,'version',v.version,'placeId',v.place_id); end if;
    if input->>'version' is null or v.version<>(input->>'version')::integer then raise exception '다른 멤버가 먼저 수정했습니다.' using errcode='40001'; end if;
  end if;
  for person in select jsonb_array_elements_text(input->'participantIds')::uuid loop
    if not private.is_group_member(gid,person) then raise exception '이 지도에 속하지 않은 참여자입니다.' using errcode='42501'; end if;
  end loop;
  if creating then
    if nullif(input->'place'->>'id','') is not null then
      select id into pid from public.places where id=(input->'place'->>'id')::uuid and group_id=gid;
      if pid is null and exists(select 1 from public.places where id=(input->'place'->>'id')::uuid) then raise exception '이 지도의 장소만 사용할 수 있습니다.' using errcode='42501'; end if;
    end if;
    if pid is null and input->'place'->>'provider'='kakao' then
      select id into pid from public.places where group_id=gid and provider='kakao' and provider_place_id=input->'place'->>'providerPlaceId';
    end if;
    if pid is null then
      insert into public.places(group_id,provider,provider_place_id,name,address,category,latitude,longitude,created_by)
      values(gid,input->'place'->>'provider',input->'place'->>'providerPlaceId',input->'place'->>'name',input->'place'->>'address',input->'place'->>'category',(input->'place'->>'latitude')::numeric,(input->'place'->>'longitude')::numeric,caller) returning id into pid;
    end if;
    insert into public.visits(group_id,place_id,visited_on,is_planned,title,note,rating,tags,marker_style,created_by,updated_by,client_request_id,last_request_id)
    values(gid,pid,(input->>'visitedOn')::date,(input->>'isPlanned')::boolean,input->>'title',input->>'note',(input->>'rating')::numeric,array(select jsonb_array_elements_text(input->'tags')),input->>'markerStyle',caller,caller,request_id,request_id) returning * into v;
  else
    update public.visits set visited_on=(input->>'visitedOn')::date,is_planned=(input->>'isPlanned')::boolean,title=input->>'title',note=input->>'note',rating=(input->>'rating')::numeric,tags=array(select jsonb_array_elements_text(input->'tags')),marker_style=input->>'markerStyle',updated_by=caller,version=version+1,last_request_id=request_id where id=v.id returning * into v;
    delete from public.visit_participants where visit_id=v.id;
  end if;
  insert into public.visit_participants(visit_id,user_id) select v.id, jsonb_array_elements_text(input->'participantIds')::uuid on conflict do nothing;
  return jsonb_build_object('id',v.id,'version',v.version,'placeId',v.place_id);
end $$;


commit;

schemas.202610100001_visit_comments.sql:
create table public.visit_comments (
  id uuid primary key,
  visit_id uuid not null references public.visits(id) on delete cascade,
  author_id uuid not null references public.profiles(id) on delete cascade,
  body text not null check (char_length(btrim(body)) between 1 and 1000),
  created_at timestamptz not null default now()
);
create index visit_comments_visit_created_idx on public.visit_comments(visit_id, created_at, id);
alter table public.visit_comments enable row level security;
create policy comments_read on public.visit_comments for select to authenticated using (
  exists(select 1 from public.visits v where v.id = visit_id and v.deleted_at is null and private.is_group_member(v.group_id))
);
revoke all on public.visit_comments from anon, authenticated;
grant select on public.visit_comments to authenticated;

-- Serialize writes with visit deletion and make retries safe with a client UUID.
create function public.add_visit_comment(target_visit uuid, comment_id uuid, comment_body text)
returns public.visit_comments language plpgsql security definer set search_path = '' as $$
declare v public.visits; saved public.visit_comments;
begin
  select * into v from public.visits where id = target_visit for update;
  if auth.uid() is null or v.id is null or v.deleted_at is not null or not private.is_group_member(v.group_id) then
    raise exception '기록에 접근할 수 없습니다.' using errcode = '42501';
  end if;
  if comment_body is null or char_length(btrim(comment_body)) not between 1 and 1000 then
    raise exception '댓글은 1~1000자로 입력해 주세요.' using errcode = '22023';
  end if;
  insert into public.visit_comments(id, visit_id, author_id, body)
    values(comment_id, target_visit, auth.uid(), btrim(comment_body)) on conflict(id) do nothing;
  select * into saved from public.visit_comments where id = comment_id;
  if saved.visit_id <> target_visit or saved.author_id <> auth.uid() then
    raise exception '댓글에 접근할 수 없습니다.' using errcode = '42501';
  end if;
  if saved.body <> btrim(comment_body) then
    raise exception '전송한 댓글을 확인한 뒤 새 댓글을 작성해 주세요.' using errcode = '40001';
  end if;
  return saved;
end $$;

create function public.delete_visit_comment(target_visit uuid, comment_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v public.visits; saved public.visit_comments;
begin
  select * into v from public.visits where id = target_visit for update;
  if auth.uid() is null or v.id is null or v.deleted_at is not null or not private.is_group_member(v.group_id) then
    raise exception '기록에 접근할 수 없습니다.' using errcode = '42501';
  end if;
  select * into saved from public.visit_comments where id = comment_id;
  if saved.id is null then return; end if;
  if saved.visit_id <> target_visit or saved.author_id <> auth.uid() then
    raise exception '본인 댓글만 삭제할 수 있습니다.' using errcode = '42501';
  end if;
  delete from public.visit_comments where id = comment_id;
end $$;
revoke all on function public.add_visit_comment(uuid,uuid,text), public.delete_visit_comment(uuid,uuid) from public, anon;
grant execute on function public.add_visit_comment(uuid,uuid,text), public.delete_visit_comment(uuid,uuid) to authenticated;

schemas.202610100002_comment_stickers.sql:
alter table public.visit_comments add column sticker_id text;
alter table public.visit_comments drop constraint visit_comments_body_check;
alter table public.visit_comments add constraint visit_comments_content_check check (
  char_length(btrim(body)) <= 1000 and (char_length(btrim(body)) > 0 or sticker_id is not null)
);
alter table public.visit_comments add constraint visit_comments_sticker_path_check check (
  sticker_id is null or (char_length(sticker_id) <= 512 and
  sticker_id ~* '^[^./\\][^/\\]*/[^./\\][^/\\]*\.(png|webp|gif)$' and
  sticker_id !~ '[[:cntrl:]]' and sticker_id !~* '\.preview\.png$')
);
create function public.add_visit_comment(target_visit uuid, comment_id uuid, comment_body text, comment_sticker_id text)
returns public.visit_comments language plpgsql security definer set search_path = '' as $$
declare v public.visits; saved public.visit_comments; cleaned text := btrim(coalesce(comment_body, ''));
begin
  select * into v from public.visits where id = target_visit for update;
  if auth.uid() is null or v.id is null or v.deleted_at is not null or not private.is_group_member(v.group_id) then
    raise exception '기록에 접근할 수 없습니다.' using errcode = '42501';
  end if;
  if char_length(cleaned) > 1000 or (cleaned = '' and comment_sticker_id is null) or
    (comment_sticker_id is not null and (char_length(comment_sticker_id) > 512 or
      comment_sticker_id !~* '^[^./\\][^/\\]*/[^./\\][^/\\]*\.(png|webp|gif)$' or
      comment_sticker_id ~ '[[:cntrl:]]' or comment_sticker_id ~* '\.preview\.png$')) then
    raise exception '댓글 내용을 확인해 주세요.' using errcode = '22023';
  end if;
  insert into public.visit_comments(id,visit_id,author_id,body,sticker_id)
    values(comment_id,target_visit,auth.uid(),cleaned,comment_sticker_id) on conflict(id) do nothing;
  select * into saved from public.visit_comments where id = comment_id;
  if saved.visit_id <> target_visit or saved.author_id <> auth.uid() then
    raise exception '댓글에 접근할 수 없습니다.' using errcode = '42501';
  end if;
  if saved.body is distinct from cleaned or saved.sticker_id is distinct from comment_sticker_id then
    raise exception '이미 전송한 댓글입니다.' using errcode = '40001';
  end if;
  return saved;
end $$;
-- Keep text-only clients compatible and apply identical retry checks.
create or replace function public.add_visit_comment(target_visit uuid, comment_id uuid, comment_body text)
returns public.visit_comments language sql security definer set search_path = '' as $$
  select public.add_visit_comment(target_visit,comment_id,comment_body,null::text);
$$;
revoke all on function public.add_visit_comment(uuid,uuid,text,text) from public,anon;
grant execute on function public.add_visit_comment(uuid,uuid,text,text) to authenticated;

schemas.202610100003_sticker_favorites.sql:
